query.base:
TS metrics-gcp.bigquery.otel-*
// slots/allocated is dual-reported on `global`; keep the bigquery_project copy only
| WHERE resource.attributes.gcp.resource_type == "bigquery_project"
  AND `metrics.bigquery.googleapis.com/slots/allocated` IS NOT NULL
// Stage 1: one value per minute per logical series (MAX collapses fragmented TSIDs of the same series)
| STATS slots = MAX(MAX_OVER_TIME(`metrics.bigquery.googleapis.com/slots/allocated`))
    BY @timestamp = TBUCKET(1 minute), resource.attributes.project_id, resource.attributes.location, attributes.reservation, attributes.job_type
// Stage 2: on-demand query slots per project per minute.
// On-demand usage has no reservation label; reserved usage is bounded by its reservation (see the reservation saturation rule).
// Minutes where the project reported slot data but no on-demand usage count as 0 on-demand slots.
| STATS on_demand_slots = SUM(slots) WHERE (attributes.reservation IS NULL OR attributes.reservation == "") AND attributes.job_type == "query"
    BY @timestamp, resource.attributes.project_id
| EVAL on_demand_slots = COALESCE(on_demand_slots, 0)
// Customise: on-demand per-project slot cap (GCP documents ~2,000 burstable slots per project; check your quota)
| EVAL slot_cap = 2000
| EVAL cap_pct = on_demand_slots * 100.0 / slot_cap
// Customise: a minute counts as saturated at >= 90% of the cap
| STATS saturated_minutes = COUNT(*) WHERE cap_pct >= 90.0,
        observed_minutes = COUNT(*),
        avg_on_demand_slots = ROUND(AVG(on_demand_slots), 1),
        peak_on_demand_slots = MAX(on_demand_slots),
        slot_cap = MAX(slot_cap)
    BY resource.attributes.project_id

breach.segment:
// Customise: alert when at/near the cap for >= 15 one-minute samples in the window.
// Slot metrics are sparse (absent while idle) and publish up to ~7 minutes late, so count
// saturated minutes rather than a share of reported minutes.
WHERE saturated_minutes >= 15
| SORT saturated_minutes DESC, peak_on_demand_slots DESC
| LIMIT 50
